// TestParseListVARHandlesEscapesAndTypes verifies that quoted NUT values and embedded escapes are decoded exactly.
func TestParseListVARHandlesEscapesAndTypes(t *testing.T) {
	input := "BEGIN LIST VAR quint\nVAR quint battery.charge \"98\"\nVAR quint ups.status \"OL \\\"ready\\\"\"\nEND LIST VAR quint\n"
	got, err := ParseListVAR(bufio.NewReader(strings.NewReader(input)), "quint")
	if err != nil {
		t.Fatal(err)
	}
	if got["battery.charge"] != "98" || got["ups.status"] != `OL "ready"` {
		t.Fatalf("got=%#v", got)
	}
}

// TestParseListVARRejectsProtocolErrorAndWrongUPS verifies rejection of server errors and mismatched response framing.
func TestParseListVARRejectsProtocolErrorAndWrongUPS(t *testing.T) {
	if _, err := ParseListVAR(bufio.NewReader(strings.NewReader("ERR UNKNOWN-UPS\n")), "quint"); err == nil {
		t.Fatal("expected error")
	}
	if _, err := ParseListVAR(bufio.NewReader(strings.NewReader("BEGIN LIST VAR other\n")), "quint"); err == nil {
		t.Fatal("expected wrong UPS error")
	}
}

// TestClientUsesOnlyListVAR verifies that the client sends only the expected read-only command and parses its response.
func TestClientUsesOnlyListVAR(t *testing.T) {
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	defer ln.Close()
	commands := make(chan string, 1)
	go func() {
		c, _ := ln.Accept()
		defer c.Close()
		line, _ := bufio.NewReader(c).ReadString('\n')
		commands <- line
		c.Write([]byte("BEGIN LIST VAR quint\nVAR quint ups.status \"OL\"\nEND LIST VAR quint\n"))
	}()
	client := Client{Address: ln.Addr().String(), Timeout: time.Second}
	got, err := client.ListVariables(context.Background(), "quint")
	if err != nil || got["ups.status"] != "OL" {
		t.Fatalf("got=%v err=%v", got, err)
	}
	if cmd := <-commands; cmd != "LIST VAR quint\n" {
		t.Fatalf("unsafe/unexpected command %q", cmd)
	}
}

type fixedVariables map[string]string

func (v fixedVariables) ListVariables(context.Context, string) (map[string]string, error) {
	return v, nil
}

func TestCollectorUsesNUTVariableNameAsStableIdentity(t *testing.T) {
	collector := Collector{Client: fixedVariables{"battery.charge": "98"}, UPS: "quint"}
	got, err := collector.Poll(context.Background())
	if err != nil || len(got) != 1 || got[0].Identity != "battery.charge" {
		t.Fatalf("metrics=%+v err=%v", got, err)
	}
}

func TestParseValueKeepsNonFiniteNUTValuesAsText(t *testing.T) {
	for _, raw := range []string{"NaN", "Inf", "+Inf", "-Inf"} {
		value, valueType := parseValue(raw)
		if value != raw || valueType != "string" {
			t.Fatalf("parseValue(%q)=(%v, %q), want unchanged string", raw, value, valueType)
		}
	}
}
